CREATE TABLE `resource_grant_audit_events` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`grant_id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`event_type` ENUM('created','extended','revoked','expired','accessed','access_denied') NOT NULL,`resource_type` VARCHAR(40) CHARACTER SET ascii NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`capability` VARCHAR(80) CHARACTER SET ascii NULL,`surface` ENUM('api','worker','export','file','event','sse') NULL,`outcome` ENUM('allowed','denied') NOT NULL,`reason` VARCHAR(500) NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`occurred_at` DATETIME(3) NOT NULL,`schema_version` SMALLINT UNSIGNED NOT NULL,PRIMARY KEY(`id`),KEY `idx_resource_grant_audit_grant`(`grant_id`,`occurred_at`),KEY `idx_resource_grant_audit_org`(`organization_id`,`occurred_at`),KEY `idx_resource_grant_audit_trace`(`trace_id`),CONSTRAINT `fk_resource_grant_audit_grant` FOREIGN KEY(`grant_id`) REFERENCES `resource_grants`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_resource_grant_audit_actor` FOREIGN KEY(`actor_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
